// UI localization. Two layers:
//   t(key, vars)  - UI strings owned by the frontend (Spanish = Latin American, default).
//   tx(text)      - strings generated by the server (rules, policy, catalog, verification, errors). The server keeps
//                   emitting canonical English; the translation happens here, and numbers/identifiers pass through
//                   untouched via capture groups, so no measured value is ever rewritten.
// Standard technical terms (ANALYZE, autovacuum, WAL, SLO, EMERGENCY STOP, rollback, lock) are intentionally kept.

const KEY = 'aidba.lang';
export let LANG = (() => {
  try { return localStorage.getItem(KEY) || 'es'; } catch { return 'es'; }
})();
export function setLang(l) {
  LANG = l;
  try { localStorage.setItem(KEY, l); } catch { /* storage unavailable: preference lasts for this page only */ }
  document.documentElement.lang = l === 'es' ? 'es-419' : 'en';
}
export const locale = () => (LANG === 'es' ? 'es-419' : 'en-US');

